UPDATE clunk_marketplace_listings SET description = '64×64 PNG 64컷으로, 8방향 각각에 8프레임짜리 여닫기 동작이 들어 있습니다. 방향당 한 줄이라 한 줄을 그대로 재생하면 됩니다 (초당 8장으로 반복 재생). 투명 배경이고 쓰인 색은 21가지이며, 시트 합계는 15.1 KB입니다. 같은 이름의 3D 상품(폴리곤 520개)을 Clunk가 그대로 찍은 것이라 모양이 같습니다. 색은 그 모델의 색에 조명을 입혀 21색으로 줄인 것이라, 3D와 나란히 놓아도 겉도지 않지만 같은 색값은 아닙니다. 각 컷의 위치와 크기, 파일 지문을 적은 목록 파일이 함께 들어 있고, Clunk 스프라이트 검사의 규격·픽셀 품질·재생 세 항목을 모두 통과했습니다.', updated_at = CURRENT_TIMESTAMP WHERE slug = 'cozy-fence-gate-swing-sprites';
